// Flattens an incoming WhatsApp webhook into one predictable shape.
//
// Two payload shapes are supported because they look nothing alike:
//   - Evolution API  -> media arrives inline as base64
//   - Meta Cloud API -> media arrives as an id you must fetch separately
// Returning [] for an item silently ends the run, which is what we want for
// delivery receipts, presence updates and our own outbound messages.

const out = [];

for (const item of $input.all()) {
  // The Webhook node nests the payload under .body
  const body = item.json.body ?? item.json;

  // ---------- Meta WhatsApp Business Cloud API ----------
  const metaValue = body?.entry?.[0]?.changes?.[0]?.value;
  if (metaValue?.messages?.length) {
    const msg = metaValue.messages[0];
    const contact = metaValue.contacts?.[0];

    let type = 'text';
    if (msg.type === 'image') type = 'image';
    else if (msg.type === 'audio' || msg.type === 'voice') type = 'audio';

    out.push({
      json: {
        source: 'meta',
        type,
        text: msg.text?.body ?? msg.image?.caption ?? '',
        // Cloud API gives only a media id; see README note on fetching it.
        base64: '',
        mediaId: msg.image?.id ?? msg.audio?.id ?? msg.voice?.id ?? '',
        mimeType: msg.image?.mime_type ?? msg.audio?.mime_type ?? '',
        phone: msg.from ?? contact?.wa_id ?? '',
        pushName: contact?.profile?.name ?? '',
        messageId: msg.id ?? '',
        timestamp: msg.timestamp
          ? new Date(Number(msg.timestamp) * 1000).toISOString()
          : new Date().toISOString(),
      },
    });
    continue;
  }

  // ---------- Evolution API ----------
  const data = body?.data ?? body;
  const m = data?.message;

  if (!m) continue;                                   // status/presence event
  if (data?.key?.fromMe) continue;                    // our own outbound reply

  const jid = data?.key?.remoteJid ?? '';
  if (jid.endsWith('@g.us')) continue;                // ignore group chats

  let type = 'text';
  if (m.imageMessage) type = 'image';
  else if (m.audioMessage || m.pttMessage) type = 'audio';

  // Evolution puts base64 in different places depending on version/settings.
  const base64 =
    data.message?.base64 ??
    m.imageMessage?.base64 ??
    m.audioMessage?.base64 ??
    data.base64 ??
    '';

  out.push({
    json: {
      source: 'evolution',
      type,
      text:
        m.conversation ??
        m.extendedTextMessage?.text ??
        m.imageMessage?.caption ??
        '',
      base64,
      mediaId: '',
      mimeType: m.imageMessage?.mimetype ?? m.audioMessage?.mimetype ?? '',
      phone: jid.split('@')[0] ?? '',
      pushName: data?.pushName ?? '',
      messageId: data?.key?.id ?? '',
      timestamp: data?.messageTimestamp
        ? new Date(Number(data.messageTimestamp) * 1000).toISOString()
        : new Date().toISOString(),
    },
  });
}

return out;

