{
  "type": "object",
  "properties": {
    "shouldEscalate": {
      "type": "boolean",
      "description": "true only if a human support agent must be alerted"
    },
    "priority": {
      "type": "string",
      "enum": [
        "urgent",
        "high",
        "medium"
      ],
      "description": "severity; must be exactly one of urgent, high, medium"
    },
    "reason": {
      "type": "string",
      "description": "one short sentence explaining why this was flagged"
    }
  },
  "required": [
    "shouldEscalate",
    "priority",
    "reason"
  ]
}

