// Builds the Firestore REST payload.
//
// Firestore's REST API needs *typed* values. createdAt MUST be timestampValue
// (not stringValue) or the Flutter app's Timestamp.toDate() returns null and
// every card shows "Unknown time".

const ALLOWED_PRIORITIES = ['urgent', 'high', 'medium'];

// Pulls an upstream item, falling back to the first if item pairing is lost.
function upstream(nodeName, index) {
  try {
    return $(nodeName).itemMatching(index).json;
  } catch (e) {
    return $(nodeName).first().json;
  }
}

return $input.all().map((item, i) => {
  // The structured output parser returns an object; a bare model may return
  // a JSON string. Accept either.
  let ai = item.json.output ?? item.json;
  if (typeof ai === 'string') {
    try {
      ai = JSON.parse(ai);
    } catch (e) {
      ai = {};
    }
  }

  const ctx = upstream('Normalize Message', i);
  const unified = upstream('Unified Message', i);

  // Clamp to the three values the Flutter Priority enum understands, so a
  // stray "critical" never renders as an Unknown grey badge.
  const rawPriority = String(ai.priority ?? '').trim().toLowerCase();
  const priority = ALLOWED_PRIORITIES.includes(rawPriority) ? rawPriority : 'medium';

  // WhatsApp gives one display name; split it into first/last for the contract.
  const nameParts = String(ctx.pushName ?? '').trim().split(/\s+/).filter(Boolean);
  const firstName = nameParts[0] ?? '';
  const lastName = nameParts.slice(1).join(' ');

  const rawPhone = String(ctx.phone ?? '').replace(/[^0-9]/g, '');
  const phone = rawPhone ? '+' + rawPhone : '';

  const message = String(unified.messageText ?? ctx.text ?? '');
  const createdAt = ctx.timestamp || new Date().toISOString();

  return {
    json: {
      shouldEscalate: ai.shouldEscalate === true || ai.shouldEscalate === 'true',
      debug: { priority, firstName, lastName, phone, messageId: ctx.messageId },
      firestore: {
        fields: {
          priority: { stringValue: priority },
          reason: { stringValue: String(ai.reason ?? '').slice(0, 500) },
          firstName: { stringValue: firstName },
          lastName: { stringValue: lastName },
          phone: { stringValue: phone },
          message: { stringValue: message.slice(0, 4000) },
          createdAt: { timestampValue: createdAt },
        },
      },
    },
  };
});
